   213	// ValidateMetadataKey checks that a metadata key is safe for use in JSON path
   214	// expressions. Keys must start with a letter or underscore and contain only
   215	// alphanumeric characters, underscores, dots, and slashes.
   216	func ValidateMetadataKey(key string) error {
