   246	// MergeMetadataJSON merges incoming metadata JSON into existing metadata.
   247	// Top-level keys from incoming overwrite keys in existing; keys only in
   248	// existing are preserved. Both inputs must be JSON objects (or empty/null).
   249	func MergeMetadataJSON(existing, incoming json.RawMessage) (json.RawMessage, error) {
