   252			trimmed := strings.TrimSpace(string(existing))
   253			if trimmed != "" && trimmed != "null" {
   254				if err := json.Unmarshal(existing, &base); err != nil {
   255					return nil, fmt.Errorf("existing metadata is not a JSON object: %w", err)
