   233	// parseComparison parses a field comparison.
   234	func (p *Parser) parseComparison() (Node, error) {
   235		if p.current.Type != TokenIdent {
   236			return nil, fmt.Errorf("expected field name at position %d, got %s", p.current.Pos, p.current.Type.String())
   237		}
   238	
   239		// Field names are case-insensitive, but the key suffix of a
   240		// metadata.<key> field keeps its original case: metadata keys are
   241		// case-sensitive JSON keys (has_metadata_key and the --metadata flag
   242		// already preserve case), so lowercasing it would make mixed-case keys
   243		// silently unqueryable.
   244		field := strings.ToLower(p.current.Value)
   245		if strings.HasPrefix(field, "metadata.") && len(field) > len("metadata.") {
   246			field = "metadata." + p.current.Value[len("metadata."):]
   247		}
   248		if err := p.advance(); err != nil {
   249			return nil, err
   250		}
   251	
   252		var op ComparisonOp
   253		switch p.current.Type {
   254		case TokenEquals:
   255			op = OpEquals
   256		case TokenNotEquals:
   257			op = OpNotEquals
   258		case TokenLess:
   259			op = OpLess
   260		case TokenLessEq:
   261			op = OpLessEq
   262		case TokenGreater:
   263			op = OpGreater
   264		case TokenGreaterEq:
   265			op = OpGreaterEq
   266		default:
   267			return nil, fmt.Errorf("expected comparison operator at position %d, got %s", p.current.Pos, p.current.Type.String())
   268		}
   269	
   270		if err := p.advance(); err != nil {
   475	
   476		switch field {
   477		case "pinned":
   478			filter.Pinned = &boolVal
   479		case "ephemeral":
   480			filter.Ephemeral = &boolVal
   481		case "template":
   482			filter.IsTemplate = &boolVal
   483		}
   484		return nil
   485	}
