   499	// applyMetadataFilter handles metadata.<key>=<value> queries (GH#1406).
   500	func (e *Evaluator) applyMetadataFilter(comp *ComparisonNode, filter *types.IssueFilter) error {
   501		if comp.Op != OpEquals {
   502			return fmt.Errorf("metadata fields only support = operator")
   503		}
   504		key := strings.TrimPrefix(comp.Field, "metadata.")
   505		if err := storage.ValidateMetadataKey(key); err != nil {
   506			return err
   507		}
   508		if filter.MetadataFields == nil {
