   527	// buildMetadataPredicate builds a predicate for metadata.<key>=<value> in OR queries.
   528	// Parses the issue's JSON metadata and compares the top-level scalar at the given key.
   529	func (e *Evaluator) buildMetadataPredicate(comp *ComparisonNode) (func(*types.Issue) bool, error) {
   530		if comp.Op != OpEquals {
   531			return nil, fmt.Errorf("metadata fields only support = operator")
   532		}
   533		key := strings.TrimPrefix(comp.Field, "metadata.")
   534		if err := storage.ValidateMetadataKey(key); err != nil {
   535			return nil, err
   536		}
   537		value := comp.Value
   538		return func(i *types.Issue) bool {
   539			if len(i.Metadata) == 0 {
   540				return false
   541			}
   542			var data map[string]json.RawMessage
   543			if err := json.Unmarshal(i.Metadata, &data); err != nil {
   544				return false
   545			}
   546			raw, ok := data[key]
   547			if !ok {
   548				return false
   549			}
   550			// Try to unmarshal as a string first (most common case)
   551			var s string
   552			if err := json.Unmarshal(raw, &s); err == nil {
   553				return s == value
   554			}
   555			// Fall back to comparing the raw JSON representation (numbers, bools)
   556			return strings.Trim(string(raw), "\"") == value
   557		}, nil
   558	}
