   560	// buildHasMetadataKeyPredicate builds a predicate for has_metadata_key=<keyname> in OR queries.
   561	func (e *Evaluator) buildHasMetadataKeyPredicate(comp *ComparisonNode) (func(*types.Issue) bool, error) {
   562		if comp.Op != OpEquals {
   563			return nil, fmt.Errorf("has_metadata_key only supports = operator")
   564		}
   565		key := comp.Value
   566		if err := storage.ValidateMetadataKey(key); err != nil {
   567			return nil, err
   568		}
   569		return func(i *types.Issue) bool {
   570			if len(i.Metadata) == 0 {
   571				return false
   572			}
   573			var data map[string]json.RawMessage
   574			if err := json.Unmarshal(i.Metadata, &data); err != nil {
   575				return false
   576			}
   577			_, ok := data[key]
   578			return ok
   579		}, nil
   580	}
